package handlers

import (
 "strconv"
 "github.com/gofiber/fiber/v2"
 "github.com/maulanashalihin/laju-go/app/services"
)

// Monitoring is read-only. Notifications are generated by the startup/hourly
// worker, never as a side effect of loading the dashboard.
func (h *OnboardingHandler) Monitoring(c *fiber.Ctx) error {
 sess,_:=h.store.Get(c)
 user:=sessionUser(sess)
 report,err:=h.service.Monitoring(c.UserContext())
 if err!=nil{
  return c.Status(fiber.StatusInternalServerError).SendString("Gagal memuat KPI onboarding")
 }
 userID:=c.Locals("user_id").(int64)
 notices,err:=h.service.UserNotices(c.UserContext(),userID)
 if err!=nil{return c.Status(fiber.StatusInternalServerError).SendString("Gagal memuat notifikasi onboarding")}
 return h.inertia.Render(c,"app/OnboardingMonitoring",fiber.Map{"user":user,"report":report,"notices":notices})
}

func (h *OnboardingHandler) MarkMonitoringNoticeRead(c *fiber.Ctx) error {
 id,err:=strconv.ParseInt(c.Params("id"),10,64)
 if err!=nil||id<=0{return onboardingHTTPError(c,services.ErrOnboardingNotFound)}
 if err:=h.service.ReadUserNotice(c.UserContext(),c.Locals("user_id").(int64),id);err!=nil{
  return onboardingHTTPError(c,err)
 }
 return c.JSON(fiber.Map{"ok":true})
}
